function categorical_s_order() {

    $(".cf-list .cf-list__item")
        .filter(function () {
            return $(this).find(".fixeditem").length > 0;
        })
        .addClass("fixeditem");


    const $list = $(".cf-list");
    const $items = $list.find(".cf-list__item");

    // Work in normal column flow and control position strictly via `order`
    $list.css("flex-direction", "column");

    // Stamp original indices
    $items.each(function (i) {
        $(this).data("origIndex", i);
    });

    // Partition items
    const $fixed = $items.filter(".fixeditem");
    const $movable = $items.not(".fixeditem");

    // Determine which "slots" are fixed (by their original index)
    const fixedSlots = new Set($fixed.map(function () {
        return $(this).data("origIndex");
    }).get());

    // Build the list of available slots (indices not taken by fixed items)
    const movableSlots = $items.map(function (i) {
        if (!fixedSlots.has(i)) return i;
    }).get();

    // Reverse the movable items (visual reversal)
    const reversedMovable = $movable.get().slice().reverse();

    // Assign orders:
    // - fixed items keep their original slot (order = original index)
    // - movable items get placed into the movable slots in reverse order
    $fixed.each(function () {
        const orig = $(this).data("origIndex");
        $(this).css("order", orig);
    });

    reversedMovable.forEach(function (el, idx) {
        const targetSlot = movableSlots[idx]; // slot index to occupy
        $(el).css("order", targetSlot);
    });
}

function hideDKREF_grid(hid_lastN,qType='default'){
    if (IntMode=='CAWI')
    {
        $('.cf-desktop-grid  table tr').add('.cf-mobile-grid-layout .cf-list').add('.cf-carousel__content-item').add('.cf-accordion-grid-answer').add('.cf-desktop-multi-grid table tr').each(function(){
        
        if(qType.toLowerCase()=='default'){
            if($(".cf-error-list__item").length==0&& ($('.cf-radio-answer--selected').length==0 ||$('.cf-checkbox--selected').length==0)){
                if($(this).hasClass('cf-table-layout__row--head') || $(this).hasClass('cf-table-layout__row--repeat-head'))
                {
                    $(this).find('th').slice(-1*hid_lastN).hide();
                }
                else
                {
                    $(this).find('td').slice(-1*hid_lastN).hide();

                }
                //Mobile
                $(this).find('.cf-list__item').slice(-1*hid_lastN).hide();
            }}
            else if(qType.toLowerCase()=='carousel')
            {
                $(this).find('.cf-list__item').slice(-1*hid_lastN).hide();

            }
            else if(qType.toLowerCase()=='accordion')
            {
                $(this).find('.cf-accordion-grid-answer__scales .cf-list__item').slice(-1*hid_lastN).hide();
            }   
        })
    }
    
    $('.cf-navigation').on('click', function (){

        if ( $('.cf-error-list__item').length>0)
        {
            $('.cf-desktop-grid  table tr').add('.cf-mobile-grid-layout .cf-list').add('.cf-desktop-multi-grid table tr').each(function () {
                $(this).find('td').slice(-1 * hid_lastN).show();

                $(this).find('th').slice(-1 * hid_lastN).show();
                
                //Mobile
                $(this).find('.cf-list__item').slice(-1 * hid_lastN).show();

            })

            //carousel
            $('.cf-carousel__content-item--current').find('.cf-list__item').slice(-1 * hid_lastN).show();
            
            //accordion
            $('.cf-collapsing-panel--open').find('.cf-list__item').slice(-1 * hid_lastN).show();
        }
    })
}

function codeOrder_grid(order,isCarousel=false) {
    if (order == "2") {
        if (isCarousel)
        { 
            
            $(".cf-carousel__content .cf-carousel__content-item").each((index,elem)=>{
                
                let listContainer = $(elem).find(".cf-list");
                let answerBtn = listContainer.find('.cf-list__item');
                var exclusive_item_count = listContainer.find(".exclusive_item_grid").length;
                reverse_grid_s_order(listContainer, answerBtn, exclusive_item_count)
            })
        
        }
        else
        {
            
                let $tr = $('.cf-desktop-grid .cf-table-layout__row--head');
                let $thElements = $tr.children('th');
                var exclusive_item_count = $(".cf-desktop-grid .exclusive_item_grid").length;
                reverse_grid_s_order($tr, $thElements, exclusive_item_count)
                $('.cf-desktop-grid .cf-table-layout__body tr').each(function () {
                    let exclusive_item_count = $(".cf-desktop-grid .exclusive_item_grid").length;
                    let $parent = $(this);
                    let $elemtToReverse = $(this).find('td');
                    reverse_grid_s_order($parent, $elemtToReverse, exclusive_item_count)
                })

                //mobile
                //revered order
                let answerLists = $(".cf-mobile-grid-layout .cf-mobile-grid-layout__answer-content .cf-list")
                answerLists.css("flex-direction", "column-reverse")

                let answerListParent = $(".cf-mobile-grid-layout .cf-mobile-grid-layout__answer-content")
                answerListParent.each(function () {
                    let exclusive_item_count=$(this).find('.exclusive_item_grid').length
                    
                    for (var i = 0; i < exclusive_item_count; i++) 

                    {   
                        $(this).find('.cf-list__item').eq(-1*(i+1)).css('order', -1 * exclusive_item_count + i)
                 
                    }
                })

        

        }

    }
}

function hideDKREF_openend() {
    if ($('.cf-checkbox--selected').length == 0) {
        $(".cf-open-answer__no-response-answer-list").add(".cf-numeric-answer__no-response-answer-list").add(".cf-numeric-list-no-response-answer-list").add(".cf-date-answer__no-response-answer-list").hide()
    }

    $(function () {
        $(".cf-page__navigation.cf-navigation button").on("click", function () {
            if ($(".cf-error-list__item").length > 0) {
                $(".cf-open-answer__no-response-answer-list").add(".cf-numeric-answer__no-response-answer-list").add(".cf-numeric-list-no-response-answer-list").add(".cf-date-answer__no-response-answer-list").show()
            }

            //error message
            $('.cf-error-list__item').each(function () {
                if ($(this).text().trim().includes('Please provide an answer.') || $(this).text().trim().includes('Please select at least 1 answer.')) {
                    $(this).text('You have not provided a response. Is that because you’re not sure, or you would prefer not to answer?');
                }
            });
        })
    })
}

function autocomplete(inp, arr, codes, qId, MinChar) {
    /*the autocomplete function takes two arguments,
    the text field element and an array of possible autocompleted values:*/
    var currentFocus;
    /*execute a function when someone writes in the text field:*/
    inp.addEventListener("input", function (e) {
        var a, b, i, val = this.value;
        /*close any already open lists of autocompleted values*/
        closeAllLists();
        if (!val||val.length<MinChar) { return false; }
        currentFocus = -1;
        /*create a DIV element that will contain the items (values):*/
        a = document.createElement("DIV");
        a.setAttribute("id", this.id + "autocomplete-list");
        a.setAttribute("class", "autocomplete-items");
        /*append the DIV element as a child of the autocomplete container:*/
        this.parentNode.appendChild(a);
        /*for each item in the array...*/
        for (i = 0; i < arr.length; i++) {
            /*Option  1 - check if the item starts with the same letters as the text field value:
            if (arr[i].substr(0, val.length).toUpperCase() == val.toUpperCase()) {*/

            /*Option  2 - check substring match */
            if (arr[i].toUpperCase().indexOf(val.toUpperCase()) > -1 ) {


                /*create a DIV element for each matching element:*/
                b = document.createElement("DIV");
                /*make the matching letters bold:*/
                b.innerHTML = "<strong>" + arr[i].substr(0, val.length) + "</strong>";
                b.innerHTML += arr[i].substr(val.length);
                /*insert a input field that will hold the current array item's value:*/
                b.innerHTML += "<input type='hidden' value='" + arr[i] + "'>";
                /*execute a function when someone clicks on the item value (DIV element):*/
                b.addEventListener("click", function (e) {
                    /*insert the value for the autocomplete text field:*/
                    inp.value = this.getElementsByTagName("input")[0].value;
                    /*close the list of autocompleted values,
                    (or any other open lists of autocompleted values:*/
                    closeAllLists();
                    setQuestionValue(qId,inp.value);
                });
                a.appendChild(b);
            }
        }
    });
    /*execute a function presses a key on the keyboard:*/
    inp.addEventListener("keydown", function (e) {
        var x = document.getElementById(this.id + "autocomplete-list");
        if (x) x = x.getElementsByTagName("div");
        if (e.keyCode == 40) {
            /*If the arrow DOWN key is pressed,
            increase the currentFocus variable:*/
            currentFocus++;
            /*and and make the current item more visible:*/
            addActive(x);
        } else if (e.keyCode == 38) { //up
            /*If the arrow UP key is pressed,
            decrease the currentFocus variable:*/
            currentFocus--;
            /*and and make the current item more visible:*/
            addActive(x);
        } else if (e.keyCode == 13) {
            /*If the ENTER key is pressed, prevent the form from being submitted,*/
            e.preventDefault();
            if (currentFocus > -1) {
                /*and simulate a click on the "active" item:*/
                if (x) {
                    x[currentFocus].click();
                   
                }
            }
        }
    });
    
    function setQuestionValue(qId, val) {

        Confirmit.page.getQuestion(qId).setValue(val);
    }

    function addActive(x) {
        /*a function to classify an item as "active":*/
        if (!x) return false;
        /*start by removing the "active" class on all items:*/
        removeActive(x);
        if (currentFocus >= x.length) currentFocus = 0;
        if (currentFocus < 0) currentFocus = (x.length - 1);
        /*add class "autocomplete-active":*/
        x[currentFocus].classList.add("autocomplete-active");
    }
    function removeActive(x) {
        /*a function to remove the "active" class from all autocomplete items:*/
        for (var i = 0; i < x.length; i++) {
            x[i].classList.remove("autocomplete-active");
        }
    }
    function closeAllLists(elmnt) {
        /*close all autocomplete lists in the document,
        except the one passed as an argument:*/
        var x = document.getElementsByClassName("autocomplete-items");
        for (var i = 0; i < x.length; i++) {
            if (elmnt != x[i] && elmnt != inp) {
                x[i].parentNode.removeChild(x[i]);
            }
        }
    }
    /*execute a function when someone clicks in the document:*/
    document.addEventListener("click", function (e) {
        closeAllLists(e.target);
    });
}

// time stamp without idle time
var jq = $.noConflict();
jq(document).ready(function(){
 var arrTime = '^f("hidCheckPart").domainLabels().toString()^';
 arrTime = arrTime.split(',');

 for(var i=0; i<arrTime.length;i++)
 {
  var input = document.createElement("input");
  input.type = "hidden";
  input.id = arrTime[i];
  input.name = arrTime[i];
  containerLOI.appendChild(input);
 }

 for(var i=0; i<arrTime.length;i++)
 {
  jq('#'+arrTime[i]).val('1');
 }
 var timer;
 var timer1;
 timer=setInterval(function(){ timeSpent() }, 1000);
    
 var Tcounter = 0;
 document.onclick = function() {
  Tcounter = 0;
 };

 document.onmousemove = function() {
  Tcounter = 0;
 };

    //document.onkeypress = function() {
    //  Tcounter = 0;
    //};

    document.onkeydown = function(){
        Tcounter = 0;
    }

 jq(window).blur(function() {
  clearInterval(timer);
  clearInterval(timer1);
 });
 jq(window).focus(function() {
  clearInterval(timer);
  timer1=setInterval(function(){ timeSpent() }, 1000);
 });

    /***[RT] can be removed after new timestamp is added****/
 function timeSpent()
 {
  var arrTime = '^f("hidCheckPart").domainLabels().toString()^';

  arrTime = arrTime.split(',');
  
        if(Tcounter<60) // counter for ideal time
  {
   for(var i=0; i<arrTime.length;i++)
   {
    var newtime = (parseInt(jq('#'+arrTime[i]).val(),10) || 0) + 1;
    
                jq('#'+arrTime[i]).val(newtime);
                
                //console.log(parseInt(jq('#' + arrTime[i]).val(), 10));
                
                Confirmit.page.serverVariables.add("myTime", parseInt(jq('#' + arrTime[i]).val(), 10));
                
                if(Confirmit.page.serverVariables.get("myTime")!=newtime){
                    //console.log("Not equal");
                    Confirmit.page.serverVariables.edit("myTime",newtime);
                }
   }
  }

  Tcounter++
 }
});


//disable copy and paste for open-end questions
function disableCopyPasteForElement(el) { 
  if (!el.dataset.copyPasteDisabled) { 
    el.addEventListener('copy', (e) => e.preventDefault()); 
    el.addEventListener('cut', (e) => e.preventDefault()); 
    el.addEventListener('paste', (e) => e.preventDefault()); 
    el.dataset.copyPasteDisabled = 'true'; // Prevents double binding 
  } 
} 

document.querySelectorAll('input, textarea').forEach(disableCopyPasteForElement); 

const observer = new MutationObserver((mutations) => { 
  for (const mutation of mutations) { 
    mutation.addedNodes.forEach((node) => { 
      if (node.nodeType === 1) { 
        if (node.matches('input, textarea')) { 
          disableCopyPasteForElement(node); 
        } else { 
          node.querySelectorAll?.('input, textarea').forEach(disableCopyPasteForElement); 
        } 
      } 
    }); 
  } 
}); 

observer.observe(document.body, { 
  childList: true, 
  subtree: true 
});

