function escapeHTMLchar(str) {
  return str.replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;")
}

// time stamp without idle time
//var jq = $.noConflict();
$(document).ready(function(){
 var arrTime = '^f("hidCheckPart").domainLabels().toString()^';
 arrTime = arrTime.split(',');

 for(var i=0; i<arrTime.length;i++)
 {
  var input = document.createElement("input");
  input.type = "hidden";
  input.id = arrTime[i];
  input.name = arrTime[i];
  containerLOI.appendChild(input);
 }

 for(var i=0; i<arrTime.length;i++)
 {
  $('#'+arrTime[i]).val('1');

 }

 var timer;
 var timer1;

 timer=setInterval(function(){ timeSpent() }, 1000);

 var Tcounter = 0;
 document.onclick = function() {
  Tcounter = 0;
 };

 document.onmousemove = function() {
  Tcounter = 0;
 };

// document.onkeypress = function() {
//  Tcounter = 0;
// };

    document.onkeydown = function(){
        Tcounter = 0;
    }

 $(window).blur(function() {
  clearInterval(timer);
  clearInterval(timer1);
 });
 $(window).focus(function() {
  clearInterval(timer);
  timer1=setInterval(function(){ timeSpent() }, 1000);
 });

 function timeSpent()
 { 
  var arrTime = '^f("hidCheckPart").domainLabels().toString()^';
  arrTime = arrTime.split(',');
  if(Tcounter<60) // counter for ideal time
  {
   for(var i=0; i<arrTime.length;i++)
   {
    var newtime = (parseInt($('#'+arrTime[i]).val(),10) || 0) + 1;
    $('#'+arrTime[i]).val(newtime);
               // console.log(parseInt($('#' + arrTime[i]).val(), 10));
                Confirmit.page.serverVariables.add("myTime", parseInt($('#' + arrTime[i]).val(), 10));
                if(Confirmit.page.serverVariables.get("myTime")!=newtime){
                    //console.log("Not equal");
                    Confirmit.page.serverVariables.edit("myTime",newtime);
                }
   }
  } 
  Tcounter++
 }
});

