// Used for hashing the API query and verifying integrity of the response retrieved from the API
// This code lives here: https://github.com/socialresearchcentre/forsta-sha256

function sha256(input) {
  // --- helpers ---
  function rrot(x, n) { return (x >>> n) | (x << (32 - n)); }
  function toHex(n) {
    n >>>= 0;
    var s = n.toString(16);
    return "00000000".slice(s.length) + s;
  }
  function toBytes(msg) {
    if (msg == null) throw new Error("sha256: null/undefined input");
    // Uint8Array / ArrayBuffer / array of numbers
    if (typeof msg !== "string") {
      if (msg instanceof Uint8Array) return Array.prototype.slice.call(msg);
      if (msg && msg.buffer instanceof ArrayBuffer) {
        return Array.prototype.slice.call(new Uint8Array(msg.buffer, msg.byteOffset || 0, msg.byteLength || msg.length));
      }
      if (Array.isArray(msg)) return msg.slice();
      throw new Error("sha256: unsupported non-string input");
    }
    // UTF-8 encode string (surrogate-safe)
    var bytes = [];
    for (var i = 0; i < msg.length; i++) {
      var c = msg.charCodeAt(i);
      if (c < 0x80) {
        bytes.push(c);
      } else if (c < 0x800) {
        bytes.push(0xC0 | (c >>> 6), 0x80 | (c & 0x3F));
      } else if (c >= 0xD800 && c <= 0xDBFF) { // surrogate pair
        var c2 = msg.charCodeAt(++i);
        var cp = ((c & 0x3FF) << 10) + (c2 & 0x3FF) + 0x10000;
        bytes.push(0xF0 | (cp >>> 18), 0x80 | ((cp >>> 12) & 0x3F),
                   0x80 | ((cp >>> 6) & 0x3F), 0x80 | (cp & 0x3F));
      } else {
        bytes.push(0xE0 | (c >>> 12), 0x80 | ((c >>> 6) & 0x3F), 0x80 | (c & 0x3F));
      }
    }
    return bytes;
  }

  var K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];

  var h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a;
  var h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;

  var bytes = toBytes(input);
  var originalLen = bytes.length;

  // Padding: append 0x80, then zeros, then 64-bit big-endian length (in bits)
  bytes.push(0x80);
  while ((bytes.length % 64) !== 56) bytes.push(0);
  var bitLenHi = Math.floor(originalLen / 0x20000000) >>> 0; // floor(len*8 / 2^32)
  var bitLenLo = (originalLen << 3) >>> 0;                    // (len*8) mod 2^32
  bytes.push((bitLenHi >>> 24) & 0xFF, (bitLenHi >>> 16) & 0xFF, (bitLenHi >>> 8) & 0xFF, bitLenHi & 0xFF,
             (bitLenLo >>> 24) & 0xFF, (bitLenLo >>> 16) & 0xFF, (bitLenLo >>> 8) & 0xFF, bitLenLo & 0xFF);

  var w = new Array(64);

  for (var i = 0; i < bytes.length; i += 64) {
    for (var j = 0; j < 16; j++) {
      var idx = i + j * 4;
      w[j] = ((bytes[idx] << 24) | (bytes[idx + 1] << 16) | (bytes[idx + 2] << 8) | (bytes[idx + 3])) >>> 0;
    }
    for (var j = 16; j < 64; j++) {
      var s0 = (rrot(w[j - 15], 7) ^ rrot(w[j - 15], 18) ^ (w[j - 15] >>> 3)) >>> 0;
      var s1 = (rrot(w[j - 2], 17) ^ rrot(w[j - 2], 19) ^ (w[j - 2] >>> 10)) >>> 0;
      w[j] = (w[j - 16] + s0 + w[j - 7] + s1) >>> 0;
    }

    var a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;

    for (var j = 0; j < 64; j++) {
      var S1 = (rrot(e, 6) ^ rrot(e, 11) ^ rrot(e, 25)) >>> 0;
      var ch = ((e & f) ^ ((~e) & g)) >>> 0;
      var T1 = (h + S1 + ch + K[j] + w[j]) >>> 0;
      var S0 = (rrot(a, 2) ^ rrot(a, 13) ^ rrot(a, 22)) >>> 0;
      var maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      var T2 = (S0 + maj) >>> 0;

      h = g; g = f; f = e;
      e = (d + T1) >>> 0;
      d = c; c = b; b = a;
      a = (T1 + T2) >>> 0;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
    h5 = (h5 + f) >>> 0;
    h6 = (h6 + g) >>> 0;
    h7 = (h7 + h) >>> 0;
  }

  return toHex(h0) + toHex(h1) + toHex(h2) + toHex(h3) +
         toHex(h4) + toHex(h5) + toHex(h6) + toHex(h7);
}

// This generates the ID passed to the RD api. 
// RD documentation specifies that this must be globally unique.
function getUniqueID() {
  const surveyId = CurrentPID();
  const respondentId = CurrentID();
  const responseId = GetResponseId();

  const uniqueResponseId = [surveyId, respondentId, responseId].join("-");
  return uniqueResponseId;
}

// uses V4 of the search API which allows for 'signing' the query before it is passed to the 
// API which prevents the respondent from tampering with the query.
function makeRDSearchURL() {

  // This might not be the same as the survey Id if you need to dedupe across multiple surveys.
  // See documentation in consts script.
  const dedupeSurveyNumber = getDedupeSurveyNumber();
  const uniqueResponseId = getUniqueID();

  const publicKey = getSearchPublicKey();
  const privateKey = getSearchPrivateKey();

  const countryCode = getCountryCode();

  let searchURL = "https://prod.rtymgt.com/api/v4/respondents/search/" +
    publicKey +
    "?sy_nr=" + encodeURIComponent(dedupeSurveyNumber) +
    "&sn_ud=" + encodeURIComponent(uniqueResponseId) +
    "&rt_cy_ce=" + encodeURIComponent(countryCode);

  const panelName = getPanelName();
  if (panelName) {
    searchURL += "&pm_sr_id=" + encodeURIComponent(panelName);
  }

  const hash = sha256(searchURL + privateKey);
  const hashedURL = searchURL + "&validation=" + hash;

  return hashedURL;
}    

// This endpoint does not support signing the URL. Instead they offer the solution 
// where we generate a token on the client side, when they pass back to us and we 
// retrieve the result from RD directly, which bypasses the possibility of client tampering.
// See readme
function makeRDActivityURL() {
  const dedupeSurveyNumber = getDedupeSurveyNumber();
  const uniqueResponseId = getUniqueID();

  const activityURL = "https://prod.resdefio.com/activity" +
    "?survey_number=" + encodeURIComponent(dedupeSurveyNumber) +
    "&session_id=" + encodeURIComponent(uniqueResponseId);

  return activityURL;
}

function makeTokenURL() {
  return "https://prod.resdefio.com/token";
}

Multi.StartupScript:
window.addEventListener("DOMContentLoaded", async () => {
  // determines how long to wait for API response before timeing out
  const TIMEOUT = "^getTimeout()^";
  const SEARCH_ENDPOINT = "^makeRDSearchURL()^";
  const EVENT_NAME = "^getSearchEventName()^";

  const RD_DELAY_MS = 100;
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  // helper function to trigger the right event
  function triggerEvent(target, eventType) {
    let el = target || document;
    el.dispatchEvent(
      new CustomEvent(eventType, { bubbles: true }),
    );
  }

  async function getRdPassParamsSafely() {
    // This is the name of the globalThis object we define in the <script> module import
    // in the OnlineIntro html
    const RD = globalThis.RD; 

    const start = performance.now();
    while (!RD || typeof RD.pass_params !== "function" || (performance.now() < (start + 1000 * 5))) {
      console.log("Waiting for RD.pass_params()");
      await sleep(100);
    }

    // waited 5 seconds and function still wasn't available
    if (!RD || typeof RD.pass_params !== "function" ) {
      console.log("RD module not available (pass_params missing).");
      return null;
    }

    // there is some async code in pass_params() according to the documentation that 
    // research defender suggests waiting 100 ms before reading the values
    await sleep(RD_DELAY_MS);

    try {
      return RD.pass_params();
    } catch (err) {
      console.log("pass_params() failed:", err);
      return null;
    }
  }

  try {
    const divSearch = document.getElementById("RD_Search");
    const question = currentQuestion;
    if (!divSearch) {
      console.log("Could not find #`RD_Search`. Check the name of the node.");
      return;
    }

    if (!question) {
      console.log("Could not find `currentQuestion`.");
      return;
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), TIMEOUT);

    let resp;
    try {
      let url = SEARCH_ENDPOINT;

      resp = await fetch(url, {
        method: "GET",
        credentials: "include",
        headers: { Accept: "application/json" },
        signal: controller.signal,
      });
    } finally {
      clearTimeout(timeoutId);
    }

    // The order of writing to the form is important because the Intro screen script checks that the status code 
    // has been filled in to determine if this has finished executing (assuming that it runs after the API getting code)

    // write the raw API response to the form
    const text = await (resp ? resp.text() : Promise.resolve(""));
    const rawEl = document.getElementById("RD_Search_raw_response");
    if (rawEl) rawEl.value = text;
    question.setValue("raw_response", text);

    // write the status code to the form
    const status = resp ? resp.status : 0;
    const statusEl = document.getElementById("RD_Search_status_code_input");
    if (statusEl) statusEl.value = status;
    question.setValue("status_code", status);

    triggerEvent(divSearch, EVENT_NAME);
    return;
  } catch (e) {
    triggerEvent(null, EVENT_NAME);
    console.log(e);
  }
});

window.addEventListener("DOMContentLoaded", async () => {
  // determines how long to wait for API response before timeing out
  const TIMEOUT = "^getTimeout()^";
  const TOKEN_ENDPOINT = "^makeTokenURL()^";
  const EVENT_NAME = "^getActivityEventName()^";
  const ACTIVITY_API_KEY = "redacted";

  // helper function to trigger the right event
  function triggerEvent(target, eventType) {
    let el = target || document;
    el.dispatchEvent(
      new CustomEvent(eventType, { bubbles: true }),
    );
  }

  // event listener wrapper guarantees that this function will be defined
  // by the time that we call it
  const rdValues = new rdCommonUtil();

  try {
    const divActivity = document.getElementById("RD_Activity");
    const question = currentQuestion;

    if (!divActivity) {
      console.log("Could not find #`RD_Activity`. Check the name of the node.");
      return;
    }

    if (!question) {
      console.log("Could not find `currentQuestion`.");
      return;
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), TIMEOUT);

    let resp;
    try {
      resp = await fetch(TOKEN_ENDPOINT, {
        method: "GET",
        headers: {
          Accept: "application/json",
          "x-api-key": ACTIVITY_API_KEY,
          // value from cookie or storage that is provided by the rdCommonUtil
          "x-ce-ud": rdValues.ce_ud,
        },
        signal: controller.signal,
      });
    } finally {
      clearTimeout(timeoutId);
    }

    // The order of writing is important because the Intro screen script checks that the status code 
    // has been filled in to determine if this has finished executing (assuming that it runs after the API getting code)

    // write the raw API response to the form
    const text = await (resp ? resp.text() : Promise.resolve(""));
    const rawEl = document.getElementById("RD_Activity_raw_token_response");
    if (rawEl) rawEl.value = text;
    question.setValue("raw_token_response", text);

    // write the status code to the form
    const status = resp ? resp.status : 0;
    const statusEl = document.getElementById("RD_Activity_status_code_input");
    if (statusEl) statusEl.value = status;
    question.setValue("status_code", status);

    triggerEvent(divActivity, EVENT_NAME);
    return;
  } catch (e) {
    triggerEvent(null, EVENT_NAME);
    console.log(e);
  }
});

Info.StartupScript:
window.addEventListener("DOMContentLoaded", async () => {
  // Helper: one-shot event wait that resolves immediately if already filled
  const waitReady = (type, { precheck } = {}) => {
    if (precheck?.()) {
      return Promise.resolve({ detail: { ok: true, prefilled: true } });
    }

    return new Promise((resolve) => {
      const handler = (e) => resolve(e);
      document.addEventListener(type, handler, { once: true });
    });
  };

  // Prefill checks handle cases where producers ran before this script
  const searchPrefilled = () => {
    const s = document.getElementById("RD_Search_status_code_input");
    return !!(s && String(s.value).trim() !== "");
  };
  const activityPrefilled = () => {
    const a = document.getElementById("RD_Activity_status_code_input");
    return !!(a && String(a.value).trim() !== "");
  };

  await Promise.all([
    waitReady("^getSearchEventName()^", { precheck: searchPrefilled }),
    waitReady("^getActivityEventName()^", { precheck: activityPrefilled }),
  ]);

  const waitingMessage = document.getElementById("RDwaitingMessage");
  const introMessage = document.getElementById("RDintroMessage");
  const introInstruction = document.getElementById("RD_introInstruction");

  if (waitingMessage) waitingMessage.hidden = true;
  if (introMessage) introMessage.hidden = false;
  if (introInstruction) introInstruction.hidden = false;

  document.documentElement.classList.remove('rd-loading');

  if ("^getProjectSettings('AUTO_SUBMIT')^".toLowerCase() === "true") {
    document.querySelector('.cf-navigation-next')?.click();
  }
});

Script.ScriptCode:
processSearchResults();
processActivityResults();
determineOverallPassFail();
// ------------------------------------------------------------------

// Determines the overall Research Defender outcome by merging the tri-state
// results from the search and activity checks. Any "1" from either branch wins,
// an indeterminate "-1" bubbles up when no branch fails but at least one is
// unresolved, and only dual "0" values produce a pass.
function determineOverallPassFail() {
  const searchQuestion = f("RD_Search");
  const activityQuestion = f("RD_Activity");

  const searchResult = searchQuestion.item("fail").valueOf();
  const activityResult = activityQuestion.item("fail").valueOf();

  let overallResult;

  if (searchResult === "1" || activityResult === "1") {
    overallResult = "1";
  } else if (searchResult === "-1" || activityResult === "-1") {
    overallResult = "-1";
  } else {
    overallResult = "0";
  }

  f("research_defender_fail").set(overallResult);
}

// Processes the SEARCH API results to determine an overal pass/fail.
function processSearchResults() {
  const FAIL_ON_API_ERROR = getRDConfig("FAIL_ON_API_ERROR");

  const searchQuestion = f("RD_Search");
  // default is to fail
  setFailItem(searchQuestion, "1");

  const statusCode = searchQuestion.item("status_code").valueOf();
  const rawResponse = searchQuestion.item("raw_response").valueOf();

  // API request failed.
  if (statusCode !== "200") {
    const errorMsg = "API HTTP Error: " + statusCode;
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(searchQuestion, errorMsg);
    } else {
      setIndeterminateResult(searchQuestion, errorMsg);
    }
    return;
  }

  // As above, if the response is empty we either fail or set indeterminate
  if (!rawResponse) {
    const errorMsg = "Successful HTTP response but empty body";
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(searchQuestion, errorMsg);
    } else {
      setIndeterminateResult(searchQuestion, errorMsg);
    }
    return;
  }

  let response;
  try {
    response = JSON.parse(rawResponse);
  } catch (e) {
    // If parsing fails, then something has gone wrong with the API response.
    // Either the API has returned an invalid object (unlikely) or the response has been
    // corrupted/tampered with
    const errorMsg = "Failed to parse JSON response: " + e.message;
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(searchQuestion, errorMsg);
    } else {
      setIndeterminateResult(searchQuestion, errorMsg);
    }
    return;
  }

  // V4 of the API returns these fields to allow for validating the integrity of the
  // API response
  let surveyValidationHash = response.Validation?.Surveys || null;
  let respondentValidationHash = response.Validation?.Respondent || null;

  // missing hashes suggests tampering. Respondent should fail
  if (!surveyValidationHash || !respondentValidationHash) {
    setFinalFailReason(searchQuestion, "Missing validation hashes in response");
    return;
  }

  const surveyString = response.String?.Surveys || null;
  const respondentString = response.String?.Respondent || null;

  if (!surveyString || !respondentString) {
    setFinalFailReason(
      searchQuestion,
      "Missing string representations in response",
    );
    return;
  }

  const isSurveyHashValid = verifyHash(surveyString, surveyValidationHash);
  const isRespondentHashValid = verifyHash(
    respondentString,
    respondentValidationHash,
  );

  if (!isSurveyHashValid || !isRespondentHashValid) {
    setFinalFailReason(
      searchQuestion,
      "Data integrity check failed, API response may have been tampered with",
    );
    return;
  }

  const surveysFields = [
    "sn_ud",
    "duplicate_potential",
    "failure_reason",
    "duplicate_score",
    "flag",
    "country_mismatch",
    "survey_number",
    "duplicate_initial_ud",
  ];

  const rdSurveyData = extractSurveyData(surveyString, surveysFields);
  updateQuestionItems(searchQuestion, rdSurveyData);

  const respondentFields = [
    "country",
    "country_code",
    "respondent_risk",
    "respondent_ud",
    "threat_potential",
    "threat_potential_score",
  ];

  const rdRespondentData = extractSurveyData(
    respondentString,
    respondentFields,
  );
  updateQuestionItems(searchQuestion, rdRespondentData);

  let shouldFail;
  try {
    shouldFail = shouldTerminate();
  } catch (e) {
    // Mark that the API response was malformed and let this person through.
    // Note that at this stage we have verified the API response has been signed
    // and has not been tampered with, so there is something wrong with the API 
    // repsonse (couldn't parse to Int etc.)
    setIndeterminateResult(
      searchQuestion,
      "Malformed API response: " + e.message,
    );
    return;
  }

  if (shouldFail) {
    setFinalFailReason(searchQuestion, "Failed Search checks");
  } else {
    setFailItem(searchQuestion, "0");
  }
}

// Contains the logic for whether a respondent should pass or fail the SEARCH API checks
// Thresholds can be adjusted and tests activated/deactivated in the RD Config
function shouldTerminate() {
  const searchQuestion = f("RD_Search");

  let threatPotentialScore = searchQuestion
    .item("threat_potential_score")
    .valueOf();
  let duplicateScore = searchQuestion.item("duplicate_score").valueOf();
  let countryMismatch = searchQuestion.item("country_mismatch").valueOf();

  threatPotentialScore = parseIntOrThrow(
    threatPotentialScore,
    "threat_potential_score",
  );
  duplicateScore = parseIntOrThrow(duplicateScore, "duplicate_score");
  countryMismatch = parseIntOrThrow(countryMismatch, "country_mismatch");

  const threatPotentialThresh = getRDConfig("THREAT_POTENTIAL_THRESHOLD");
  const duplicateScoreThresh = getRDConfig("DUPLICATE_SCORE_THRESHOLD");
  const countryMismatchCheck = getRDConfig("COUNTRY_MISMATCH_CHECK");


  let duplicateScoreFail =
    duplicateScoreThresh && duplicateScore >= duplicateScoreThresh;

  // There is an edge case where a respondent can trigger a duplicate score fail to themselves,
  // i.e. their sn_ud matches the duplicate_initial_ud. We should not fail them.
  const sn_id = searchQuestion.item("sn_ud").valueOf();
  const duplicate_initial_ud = searchQuestion
    .item("duplicate_initial_ud")
    .valueOf();

  if (duplicateScoreFail && !sn_id) {
    throw new Error(
      "threat_potential_score indicates fail but sn_ud is missing",
    );
  }

  if (duplicateScoreFail && !duplicate_initial_ud) {
    throw new Error(
      "threat_potential_score indicates fail but duplicate_initial_ud is missing",
    );
  }

  const isSelfDuplicate = sn_id === duplicate_initial_ud;
  duplicateScoreFail = duplicateScoreFail && !isSelfDuplicate;

  const threatPotentialFail =
    threatPotentialThresh && threatPotentialScore >= threatPotentialThresh;

  const countryFail = countryMismatchCheck && countryMismatch === 1;

  return threatPotentialFail || duplicateScoreFail || countryFail;
}

function parseIntOrThrow(value, fieldName) {
  const intValue = parseInt(value, 10);
  if (Number.isNaN(intValue)) {
    throw new Error(`Failed to parse ${fieldName} ("${value}") as integer`);
  }
  return intValue;
}

// Processes the ACTIVITY results and determines overall pass/fail
function processActivityResults() {
  const FAIL_ON_API_ERROR = getRDConfig("ACTIVITY_FAIL_ON_API_ERROR");
  const ACTIVITY_COUNT_THRESHOLD = getRDConfig("ACTIVITY_COUNT_THRESHOLD");

  const activityQuestion = f("RD_Activity");
  const statusCode = activityQuestion.item("status_code").valueOf();
  const rawResponse = activityQuestion.item("raw_token_response").valueOf();

  // default it to fail
  setFailItem(activityQuestion, "1");

  // see comments in processSearchResults about API failure logic.
  if (statusCode !== "200") {
    const errorMsg = "API HTTP Error: " + statusCode;
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  if (!rawResponse) {
    const errorMsg = "Successful HTTP response but empty body";
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  let parsedResponse;
  try {
    parsedResponse = JSON.parse(rawResponse);
  } catch (e) {
    const errorMsg = "Failed to parse JSON token response: " + e.message;
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  const token = parsedResponse?.Results?.[0]?.Tokens?.[0] || null;
  if (!token) {
    const errorMsg = "No token found in API response";
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  const activityURL = makeRDActivityURL();
  const headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Headers": "token",
    "x-api-key": getActivityPublicKey(),
    token: token,
  };

  let resp;

  try {
    resp = Http.Get(activityURL, null, headers);
  } catch (e) {
    const errorMsg = "Failed to fetch activity data: " + e.message;
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  // we only have access to the body as text
  // if empty, then an unknown error
  if (!resp) {
    const errorMsg = "Empty body returned from activity endpoint";
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  activityQuestion.item("raw_response").set(resp);

  let respJson;
  try {
    respJson = JSON.parse(resp);
  } catch (e) {
    setIndeterminateResult(
      activityQuestion,
      "Failed to parse JSON activity response: " + e.message,
    );
    return;
  }

  const message = respJson?.message || null;

  if (message && message.toLowerCase() === "this token has already been used") {
    const errorMsg = "Respondent supplied a reused token";
    // We don't want to fail on this if we are not failing on API errors. When everything in the 
    // config is set to false, we shouldn't fail anyone, so need to be able to disable these one.
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  if (message && message.toLowerCase() === "this token does not exist") {
    const errorMsg = "Respondent supplied an invalid token";
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  const statistics = respJson?.Statistics?.[0]?.Activity?.Token;

  if (!statistics) {
    setIndeterminateResult(
      activityQuestion,
      "No statistics found in activity response",
    );
    return;
  }

  const statsToExtract = [
    "Count",
    "Average",
    "Ratio",
    "Median",
    "StandardDeviation",
  ];

  for (const stat of statsToExtract) {
    const value = statistics[stat] ?? null;
    activityQuestion.item(stat).set(value);
  }

  const count = statistics["Count"] ?? null;
  if (count === null) {
    setIndeterminateResult(
      activityQuestion,
      "No Count found in activity statistics",
    );
    return;
  }

  const countInt = parseInt(count, 10);
  if (Number.isNaN(countInt)) {
    setIndeterminateResult(
      activityQuestion,
      `Failed to parse Count "${count}" as integer`,
    );
    return;
  }

  if (ACTIVITY_COUNT_THRESHOLD && countInt >= ACTIVITY_COUNT_THRESHOLD) {
    setFinalFailReason(
      activityQuestion,
      "Respondent activity too high: " + countInt,
    );
    return;
  }

  setFailItem(activityQuestion, "0");
}

// helper to extract the API response from the invalid JSON string.
function extractSurveyData(surveysString, fieldsToExtract) {
  let extractedData = {};
  for (const v of fieldsToExtract) {
    const regex = new RegExp(`${v}:([^,}\\]]+)`);
    const match = surveysString.match(regex);
    if (match && match[1]) {
      extractedData[v] = match[1];
    }
  }

  return extractedData;
}

// helper to update MR text questions
function updateQuestionItems(question, data) {
  for (const v in data) question.item(v).set(data[v]);
}

function setFinalFailReason(question, reason) {
  question.item("final_fail_reason").set(reason);
}

function setFailItem(question, failValue) {
  question.item("fail").set(failValue);
}

function setIndeterminateResult(question, reason) {
  setFinalFailReason(question, reason);
  setFailItem(question, "-1");
}

// Verfies that the hash and string returned from the API match
function verifyHash(dataString, expectedHash) {
  const privateKey = getSearchPrivateKey();
  const computedHash = sha256(dataString + privateKey);
  return computedHash === expectedHash;
}

